class PetriNet:
    def __init__(self, places, transitions, arcs, initial, final):
        self.places = tuple(places)
        self.transitions = tuple(sorted(transitions))
        self.arcs = set(arcs)
        self.initial = self.places.index(initial)
        self.final = self.places.index(final)
        self.inputs = {}
        self.outputs = {}
        for transition in self.transitions:
            self.inputs[transition] = tuple(index for index, place in enumerate(self.places)
                                            if (place, transition) in self.arcs)
            self.outputs[transition] = tuple(index for index, place in enumerate(self.places)
                                             if (transition, place) in self.arcs)
        self.routes = [tuple(transition for transition in self.transitions
                             if (place, transition) in self.arcs) for place in self.places]
        self.initial_marking = tuple(int(index == self.initial) for index in range(len(self.places)))
        self.final_marking = tuple(int(index == self.final) for index in range(len(self.places)))

    def enabled(self, marking, transition):
        return all(marking[index] >= 1 for index in self.inputs[transition])

    def enabled_transitions(self, marking):
        return tuple(transition for transition in self.transitions if self.enabled(marking, transition))

    def fire(self, marking, transition):
        result = list(marking)
        for index in self.inputs[transition]:
            result[index] -= 1
        for index in self.outputs[transition]:
            result[index] += 1
        return tuple(result)


def read_model():
    places = []
    transitions = []
    arcs = []
    for line in Path("input/model.txt").read_text(encoding="ascii").splitlines():
        kind, *values = line.split(" ")
        if kind == "PLACE":
            places.append(values[0])
        elif kind == "TRANSITION":
            transitions.append(values[0])
        elif kind == "ARC":
            arcs.append(tuple(values))
        elif kind == "INITIAL":
            initial = values[0]
        else:
            final = values[0]
    return PetriNet(places, transitions, arcs, initial, final)


class ReplayTotals:
    def __init__(self, place_count):
        self.missing = 0
        self.remaining = 0
        self.consumed = 0
        self.produced = 0
        self.skipped = 0
        self.place_missing = [0] * place_count
        self.place_remaining = [0] * place_count
        self.deviating = [0] * place_count
        self.waiting = [[] for _ in range(place_count)]
        self.routes = [Counter() for _ in range(place_count)]

    def fitness(self):
        return (Fraction(1, 2) * (1 - Fraction(self.missing, self.consumed))
                + Fraction(1, 2) * (1 - Fraction(self.remaining, self.produced)))

from collections import Counter


def directly_follows(log):
    counts = Counter()
    for trace, weight in log:
        for first, second in zip(trace, trace[1:]):
            counts[first, second] += weight
    return counts


def basic_relation(counts, first, second):
    forward = counts[first, second] > 0
    backward = counts[second, first] > 0
    if forward and not backward:
        return "->"
    if backward and not forward:
        return "<-"
    return "||" if forward else "#"


def table(rows, width):
    size = len(rows)
    lines = ["    " + "".join(f"{number:>{width}}" for number in range(1, size + 1))]
    for number, row in enumerate(rows, 1):
        lines.append(f"{number:>4}" + "".join(f"{str(value):>{width}}" for value in row))
    return lines


def footprint(activities, relation):
    lines = [f"ACTIVITY {number} {activity}" for number, activity in enumerate(activities, 1)]
    rows = [[relation(first, second) for second in activities] for first in activities]
    lines.extend(table(rows, 4))
    return lines

from collections import defaultdict
from fractions import Fraction
from pathlib import Path


MONTH_DAYS = (31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)


class Event:
    def __init__(self, line, case_id, activity, timestamp, resource, time):
        self.line = line
        self.case_id = case_id
        self.activity = activity
        self.timestamp = timestamp
        self.resource = resource
        self.time = time


class Case:
    def __init__(self, identifier, events):
        self.identifier = identifier
        self.events = sorted(events, key=lambda event: (event.time, event.line))
        self.trace = tuple(event.activity for event in self.events)
        self.duration = self.events[-1].time - self.events[0].time


def read_inputs():
    lines = Path("input/eventlog.csv").read_text(encoding="ascii").splitlines()
    rows = [(number, *line.split(",")) for number, line in enumerate(lines[1:], 2)]
    parameters = {}
    for line in Path("input/params.txt").read_text(encoding="ascii").splitlines():
        name, value = line.split(" ")
        parameters[name] = value
    return rows, parameters


def timestamp_minutes(timestamp):
    month = int(timestamp[5:7])
    day = int(timestamp[8:10])
    hour = int(timestamp[11:13])
    minute = int(timestamp[14:16])
    if not 1 <= month <= 12:
        return None
    if not 1 <= day <= MONTH_DAYS[month - 1]:
        return None
    if not 0 <= hour <= 23 or not 0 <= minute <= 59:
        return None
    return ((sum(MONTH_DAYS[:month - 1]) + day - 1) * 24 + hour) * 60 + minute


def group_cases(events):
    grouped = defaultdict(list)
    for event in events:
        grouped[event.case_id].append(event)
    return [Case(identifier, grouped[identifier]) for identifier in sorted(grouped)]


def median(values):
    values = sorted(values)
    middle = len(values) // 2
    if len(values) % 2:
        return Fraction(values[middle])
    return Fraction(values[middle - 1] + values[middle], 2)

from fractions import Fraction


def dependency(counts, first, second):
    forward = counts[first, second]
    backward = counts[second, first]
    return Fraction(forward - backward, forward + backward + 1)


def loop_measure(count):
    return Fraction(count, count + 1)


def split_measure(counts, activity, first, second):
    numerator = counts[first, second] + counts[second, first]
    denominator = counts[activity, first] + counts[activity, second] + 1
    return Fraction(numerator, denominator)


def join_measure(counts, activity, first, second):
    numerator = counts[first, second] + counts[second, first]
    denominator = counts[first, activity] + counts[second, activity] + 1
    return Fraction(numerator, denominator)
